import{_ as t,o as a,c as n,ag as s}from"./chunks/framework.BtkZWVrG.js";const g=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md"}'),r={name:"guide/architecture.md"};function i(o,e,d,l,c,p){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Luke Core Engine is a Spring Boot 3.4 application wrapping <strong>CIBSeven 2.1.0</strong> (Camunda 7 fork) with an embedded PostgreSQL database and a custom React frontend.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                   Luke Core UI                   │</span></span>
<span class="line"><span>│              (React 19 + Vite SPA)               │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│                 Spring Boot 3.4                  │</span></span>
<span class="line"><span>│  ┌────────────┐ ┌─────────────┐ ┌─────────────┐ │</span></span>
<span class="line"><span>│  │  CIBSeven  │ │  Luke APIs  │ │  Security   │ │</span></span>
<span class="line"><span>│  │ Engine REST│ │  /api/*     │ │  Filters    │ │</span></span>
<span class="line"><span>│  │ /engine-   │ │  - database │ │  - Auth     │ │</span></span>
<span class="line"><span>│  │  rest/*    │ │  - topics   │ │  - Tenant   │ │</span></span>
<span class="line"><span>│  └─────┬──────┘ └──────┬──────┘ └─────────────┘ │</span></span>
<span class="line"><span>│        │               │                         │</span></span>
<span class="line"><span>│  ┌─────┴───────────────┴──────────────────────┐  │</span></span>
<span class="line"><span>│  │         CIBSeven Process Engine            │  │</span></span>
<span class="line"><span>│  │  BPMN | CMMN | DMN | History | Jobs        │  │</span></span>
<span class="line"><span>│  └─────────────────┬──────────────────────────┘  │</span></span>
<span class="line"><span>│                    │                              │</span></span>
<span class="line"><span>│  ┌─────────────────┴──────────────────────────┐  │</span></span>
<span class="line"><span>│  │         Embedded PostgreSQL 14             │  │</span></span>
<span class="line"><span>│  │         (io.zonky.test)                    │  │</span></span>
<span class="line"><span>│  └────────────────────────────────────────────┘  │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────┘</span></span></code></pre></div><h2 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;">​</a></h2><h3 id="cibseven-process-engine" tabindex="-1">CIBSeven Process Engine <a class="header-anchor" href="#cibseven-process-engine" aria-label="Permalink to &quot;CIBSeven Process Engine&quot;">​</a></h3><p>The core BPMN workflow engine providing:</p><ul><li><strong>Process Definitions</strong> — Deploy and manage BPMN 2.0 process models</li><li><strong>Process Instances</strong> — Start and monitor running workflows</li><li><strong>User Tasks</strong> — Human task management with assignment</li><li><strong>External Tasks</strong> — Distributed task execution via topic-based polling</li><li><strong>Jobs</strong> — Timer events, async continuations, retries</li><li><strong>Incidents</strong> — Failed job tracking and resolution</li><li><strong>History</strong> — Full audit trail of all engine operations</li><li><strong>DMN Decisions</strong> — Decision table evaluation</li></ul><h3 id="rest-api-layers" tabindex="-1">REST API Layers <a class="header-anchor" href="#rest-api-layers" aria-label="Permalink to &quot;REST API Layers&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Layer</th><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td>CIBSeven REST</td><td><code>/engine-rest/*</code></td><td>Standard Camunda 7 REST API</td></tr><tr><td>Luke APIs</td><td><code>/api/*</code></td><td>Custom database explorer, topic registry</td></tr><tr><td>Actuator</td><td><code>/actuator/*</code></td><td>Health, info, metrics</td></tr></tbody></table><h3 id="security-filters" tabindex="-1">Security Filters <a class="header-anchor" href="#security-filters" aria-label="Permalink to &quot;Security Filters&quot;">​</a></h3><p>Requests pass through filters in order:</p><ol><li><strong>Spring Security</strong> — CORS, CSRF disabled, permits all</li><li><strong>RestApiAuthFilter</strong> (order 1) — HTTP Basic auth on <code>/engine-rest/*</code></li><li><strong>TenantFilter</strong> (order 2) — Enforces <code>X-Tenant-Id</code> header on <code>/engine-rest/*</code></li></ol><h3 id="embedded-postgresql" tabindex="-1">Embedded PostgreSQL <a class="header-anchor" href="#embedded-postgresql" aria-label="Permalink to &quot;Embedded PostgreSQL&quot;">​</a></h3><p>Uses <code>io.zonky.test:embedded-postgres</code> to start a real PostgreSQL instance on application boot:</p><ul><li><strong>No Docker required</strong> — Binary extracted and run automatically</li><li><strong>Persistent data</strong> — Stored in <code>./luke-data/postgres</code></li><li><strong>Port 5432</strong> — Standard PostgreSQL port</li><li><strong>Profile</strong> — Activated via <code>spring.profiles.active=embedded</code></li></ul><h3 id="ui-architecture" tabindex="-1">UI Architecture <a class="header-anchor" href="#ui-architecture" aria-label="Permalink to &quot;UI Architecture&quot;">​</a></h3><p>React 19 SPA built with:</p><ul><li><strong>Vite 8</strong> — Build tool with HMR</li><li><strong>TanStack Query</strong> — Server state management</li><li><strong>TanStack Table</strong> — Data tables</li><li><strong>Zustand</strong> — Client state (auth, tenant, UI)</li><li><strong>React Router 6</strong> — Client-side routing</li><li><strong>Tailwind CSS 4</strong> — Styling</li><li><strong>bpmn-js</strong> — BPMN diagram viewer</li></ul><p>The UI is built and bundled into the Spring Boot JAR as static resources at <code>/src/main/resources/static/</code>.</p><h2 id="multi-tenancy" tabindex="-1">Multi-Tenancy <a class="header-anchor" href="#multi-tenancy" aria-label="Permalink to &quot;Multi-Tenancy&quot;">​</a></h2><p>All engine REST API requests require tenant identification:</p><ul><li><strong>Header</strong>: <code>X-Tenant-Id: &lt;tenant-id&gt;</code></li><li><strong>Query param</strong>: <code>tenantIdIn=&lt;tenant-id&gt;</code></li></ul><p>Exempt paths: <code>/engine-rest/engine</code>, <code>/engine-rest/tenant</code>, <code>/engine-rest/user</code>, <code>/engine-rest/group</code>, <code>/engine-rest/identity</code></p><p>A default tenant is auto-created on first startup.</p><h2 id="database-schema" tabindex="-1">Database Schema <a class="header-anchor" href="#database-schema" aria-label="Permalink to &quot;Database Schema&quot;">​</a></h2><p>The engine creates approximately 50 tables:</p><table tabindex="0"><thead><tr><th>Prefix</th><th>Purpose</th></tr></thead><tbody><tr><td><code>ACT_RU_*</code></td><td>Runtime data (active instances, tasks, jobs)</td></tr><tr><td><code>ACT_HI_*</code></td><td>Historical data (completed instances, audit)</td></tr><tr><td><code>ACT_RE_*</code></td><td>Repository (deployments, process definitions)</td></tr><tr><td><code>ACT_ID_*</code></td><td>Identity (users, groups, tenants, memberships)</td></tr><tr><td><code>ACT_GE_*</code></td><td>General (properties, byte arrays, schema log)</td></tr><tr><td><code>luke_*</code></td><td>Custom Luke tables (topic registry)</td></tr></tbody></table>`,28)])])}const h=t(r,[["render",i]]);export{g as __pageData,h as default};
